//! Snapshot diff. Produces a [`Plan`]: an explainable list of changes that turns
//! the `current` snapshot (an environment) into the `desired` one (git / another
//! environment). The plan is pure data: SQL is generated by the engine.

use std::collections::{BTreeMap, BTreeSet};

use serde::{Deserialize, Serialize};

use crate::model::*;

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "op", rename_all = "snake_case")]
pub enum Change {
    CreateCollection { collection: Collection },
    DropCollection { collection: Collection },
    RenameCollection { from: String, to: String },
    UpdateCollection { name: String, before: CollectionHeader, after: CollectionHeader },
    AddField { collection: String, field: Field },
    DropField { collection: String, field: Field },
    RenameField { collection: String, from: String, to: String },
    AlterField { collection: String, before: Field, after: Field },
    UpsertRole { before: Option<Role>, after: Role },
    DeleteRole { role: Role },
    UpsertPolicy { before: Option<Policy>, after: Policy },
    DeletePolicy { policy: Policy },
    UpsertFlow { before: Option<crate::flow::Flow>, after: crate::flow::Flow },
    DeleteFlow { flow: crate::flow::Flow },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Risk {
    /// Metadata or additive change.
    Safe,
    /// May fail on existing data (e.g. NOT NULL on a populated column, type cast).
    Risky,
    /// Data is deleted.
    Destructive,
}

impl Change {
    pub fn risk(&self) -> Risk {
        match self {
            Change::DropCollection { .. } => Risk::Destructive,
            Change::DropField { field, .. } => {
                if field.has_column() {
                    Risk::Destructive
                } else {
                    Risk::Safe
                }
            }
            Change::UpdateCollection { before, after, .. } => {
                if before.system_fields && !after.system_fields {
                    Risk::Destructive
                } else {
                    Risk::Safe
                }
            }
            Change::AlterField { before, after, .. } => {
                if before.pg_type() != after.pg_type() {
                    if is_widening(before, after) {
                        Risk::Safe
                    } else {
                        Risk::Destructive
                    }
                } else if (!before.required && after.required) || (!before.unique && after.unique) {
                    Risk::Risky
                } else {
                    Risk::Safe
                }
            }
            Change::AddField { field, .. } => {
                if field.required && field.default.is_none() && field.has_column() {
                    Risk::Risky
                } else {
                    Risk::Safe
                }
            }
            _ => Risk::Safe,
        }
    }

    pub fn summary(&self) -> String {
        match self {
            Change::CreateCollection { collection } => {
                format!("+ collection {} ({} fields)", collection.name, collection.fields.len())
            }
            Change::DropCollection { collection } => format!("- collection {} (DATA LOSS)", collection.name),
            Change::RenameCollection { from, to } => format!("~ collection {from} -> {to}"),
            Change::UpdateCollection { name, before, after } => {
                let mut what = vec![];
                if before.meta != after.meta {
                    what.push("meta");
                }
                if before.sync != after.sync {
                    what.push("sync");
                }
                if before.system_fields != after.system_fields {
                    what.push("system_fields");
                }
                format!("~ collection {name}: {}", what.join(", "))
            }
            Change::AddField { collection, field } => {
                format!("+ field {collection}.{} ({})", field.name, field.ty.as_str())
            }
            Change::DropField { collection, field } => format!(
                "- field {collection}.{}{}",
                field.name,
                if field.has_column() { " (DATA LOSS)" } else { "" }
            ),
            Change::RenameField { collection, from, to } => format!("~ field {collection}.{from} -> {to}"),
            Change::AlterField { collection, before, after } => {
                format!("~ field {collection}.{}: {}", after.name, describe_field_change(before, after).join(", "))
            }
            Change::UpsertRole { before: None, after } => format!("+ role {}", after.name),
            Change::UpsertRole { after, .. } => format!("~ role {}", after.name),
            Change::DeleteRole { role } => format!("- role {}", role.name),
            Change::UpsertPolicy { before: None, after } => format!("+ policy {}", after.name),
            Change::UpsertPolicy { after, .. } => format!("~ policy {}", after.name),
            Change::DeletePolicy { policy } => format!("- policy {}", policy.name),
            Change::UpsertFlow { before: None, after } => format!("+ flow {}", after.name),
            Change::UpsertFlow { after, .. } => format!("~ flow {}", after.name),
            Change::DeleteFlow { flow } => format!("- flow {}", flow.name),
        }
    }
}

fn is_widening(before: &Field, after: &Field) -> bool {
    use FieldType::*;
    match (before.ty, after.ty) {
        (String, String) => after.max_length.unwrap_or(255) >= before.max_length.unwrap_or(255),
        (String, Text) => true,
        (Integer, BigInteger) | (Integer, Float) | (Integer, Decimal) | (BigInteger, Decimal) => true,
        (Date, Datetime) => true,
        // m2o <-> file <-> uuid keep the same uuid column
        (a, b) => before.pg_type() == after.pg_type() && a != b,
    }
}

pub fn describe_field_change(before: &Field, after: &Field) -> Vec<String> {
    let mut out = vec![];
    if before.ty != after.ty || before.pg_type() != after.pg_type() {
        out.push(format!(
            "type {} -> {}",
            before.pg_type().unwrap_or_else(|| before.ty.as_str().into()),
            after.pg_type().unwrap_or_else(|| after.ty.as_str().into())
        ));
    }
    if before.required != after.required {
        out.push(if after.required { "required".into() } else { "nullable".into() });
    }
    if before.unique != after.unique {
        out.push(if after.unique { "unique".into() } else { "not unique".into() });
    }
    if before.indexed != after.indexed {
        out.push(if after.indexed { "indexed".into() } else { "not indexed".into() });
    }
    if before.default != after.default {
        out.push("default".into());
    }
    if before.relation != after.relation {
        out.push("relation".into());
    }
    if before.validation != after.validation {
        out.push("validation".into());
    }
    if before.meta != after.meta {
        out.push("meta".into());
    }
    out
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Plan {
    /// Hash of the snapshot the plan was computed against. Applying the plan to an
    /// environment whose hash differs is refused (it changed in the meantime).
    pub from_hash: String,
    /// Hash the environment will have after applying the plan.
    pub to_hash: String,
    pub changes: Vec<Change>,
    #[serde(default)]
    pub warnings: Vec<String>,
}

impl Plan {
    pub fn is_empty(&self) -> bool {
        self.changes.is_empty()
    }
    pub fn max_risk(&self) -> Risk {
        let mut risk = Risk::Safe;
        for c in &self.changes {
            match c.risk() {
                Risk::Destructive => return Risk::Destructive,
                Risk::Risky => risk = Risk::Risky,
                Risk::Safe => {}
            }
        }
        risk
    }
    pub fn has_destructive(&self) -> bool {
        self.max_risk() == Risk::Destructive
    }
    pub fn summary_lines(&self) -> Vec<String> {
        self.changes
            .iter()
            .map(|c| {
                let tag = match c.risk() {
                    Risk::Safe => "",
                    Risk::Risky => " [risky]",
                    Risk::Destructive => " [destructive]",
                };
                format!("{}{}", c.summary(), tag)
            })
            .collect()
    }
}

/// Compute the changes that turn `current` into `desired`.
pub fn diff(current: &Snapshot, desired: &Snapshot) -> Plan {
    let (mut current_patched, mut desired_patched) = (current.clone(), desired.clone());
    current_patched.ensure_admin();
    desired_patched.ensure_admin();
    let (current, desired) = (&current_patched, &desired_patched);
    let mut changes = Vec::new();
    let mut warnings = Vec::new();

    let current_by_name: BTreeMap<&str, &Collection> =
        current.collections.iter().map(|c| (c.name.as_str(), c)).collect();
    let desired_names: BTreeSet<&str> = desired.collections.iter().map(|c| c.name.as_str()).collect();
    let mut matched: BTreeSet<&str> = BTreeSet::new();

    let mut desired_sorted: Vec<&Collection> = desired.collections.iter().collect();
    desired_sorted.sort_by(|a, b| a.name.cmp(&b.name));

    for d in desired_sorted {
        let existing = match current_by_name.get(d.name.as_str()) {
            Some(c) => Some(*c),
            None => match &d.renamed_from {
                Some(old) if !desired_names.contains(old.as_str()) && !matched.contains(old.as_str()) => {
                    current_by_name.get(old.as_str()).copied()
                }
                Some(old) => {
                    warnings.push(format!("collection {}: renamed_from `{old}` ignored (not applicable)", d.name));
                    None
                }
                None => None,
            },
        };

        match existing {
            None => {
                let mut c = d.clone();
                c.renamed_from = None;
                for f in &mut c.fields {
                    f.renamed_from = None;
                }
                changes.push(Change::CreateCollection { collection: c });
            }
            Some(cur) => {
                matched.insert(cur.name.as_str());
                if cur.name != d.name {
                    changes.push(Change::RenameCollection { from: cur.name.clone(), to: d.name.clone() });
                }
                if cur.header() != d.header() {
                    changes.push(Change::UpdateCollection {
                        name: d.name.clone(),
                        before: cur.header(),
                        after: d.header(),
                    });
                }
                diff_fields(cur, d, &mut changes, &mut warnings);
            }
        }
    }

    let mut current_sorted: Vec<&Collection> = current.collections.iter().collect();
    current_sorted.sort_by(|a, b| a.name.cmp(&b.name));
    for c in current_sorted {
        if !matched.contains(c.name.as_str()) {
            changes.push(Change::DropCollection { collection: c.clone() });
        }
    }

    // Access control: matched by stable id.
    let cur_roles: BTreeMap<_, _> = current.roles.iter().map(|r| (r.id, r)).collect();
    let des_roles: BTreeMap<_, _> = desired.roles.iter().map(|r| (r.id, r)).collect();
    let cur_pol: BTreeMap<_, _> = current.policies.iter().map(|p| (p.id, p)).collect();
    let des_pol: BTreeMap<_, _> = desired.policies.iter().map(|p| (p.id, p)).collect();

    for (id, p) in &des_pol {
        match cur_pol.get(id) {
            None => changes.push(Change::UpsertPolicy { before: None, after: (*p).clone() }),
            Some(c) if normalized_policy(c) != normalized_policy(p) => {
                changes.push(Change::UpsertPolicy { before: Some((*c).clone()), after: (*p).clone() })
            }
            _ => {}
        }
    }
    for (id, r) in &des_roles {
        match cur_roles.get(id) {
            None => changes.push(Change::UpsertRole { before: None, after: (*r).clone() }),
            Some(c) if normalized_role(c) != normalized_role(r) => {
                changes.push(Change::UpsertRole { before: Some((*c).clone()), after: (*r).clone() })
            }
            _ => {}
        }
    }
    for (id, r) in &cur_roles {
        if !des_roles.contains_key(id) {
            if *id == ADMIN_ROLE_ID {
                warnings.push("the Administrator role cannot be deleted: kept".into());
                continue;
            }
            changes.push(Change::DeleteRole { role: (*r).clone() });
        }
    }
    for (id, p) in &cur_pol {
        if !des_pol.contains_key(id) {
            if *id == ADMIN_POLICY_ID {
                warnings.push("the Administrator policy cannot be deleted: kept".into());
                continue;
            }
            changes.push(Change::DeletePolicy { policy: (*p).clone() });
        }
    }

    // Flows: matched by stable id.
    let cur_flows: BTreeMap<_, _> = current.flows.iter().map(|f| (f.id, f)).collect();
    let des_flows: BTreeMap<_, _> = desired.flows.iter().map(|f| (f.id, f)).collect();
    for (id, f) in &des_flows {
        match cur_flows.get(id) {
            None => changes.push(Change::UpsertFlow { before: None, after: (*f).clone() }),
            Some(c) if **c != **f => changes.push(Change::UpsertFlow { before: Some((*c).clone()), after: (*f).clone() }),
            _ => {}
        }
    }
    for (id, f) in &cur_flows {
        if !des_flows.contains_key(id) {
            changes.push(Change::DeleteFlow { flow: (*f).clone() });
        }
    }

    Plan { from_hash: current.hash(), to_hash: desired.hash(), changes, warnings }
}

fn normalized_role(r: &Role) -> Role {
    let mut r = r.clone();
    r.policies.sort();
    r.policies.dedup();
    r
}

fn normalized_policy(p: &Policy) -> Policy {
    let mut p = p.clone();
    p.permissions.sort_by(|a, b| (a.collection.as_str(), a.action).cmp(&(b.collection.as_str(), b.action)));
    p
}

fn diff_fields(cur: &Collection, des: &Collection, changes: &mut Vec<Change>, warnings: &mut Vec<String>) {
    let coll = des.name.clone();
    let cur_by_name: BTreeMap<&str, &Field> = cur.fields.iter().map(|f| (f.name.as_str(), f)).collect();
    let des_names: BTreeSet<&str> = des.fields.iter().map(|f| f.name.as_str()).collect();
    let mut matched: BTreeSet<&str> = BTreeSet::new();

    for d in &des.fields {
        let existing = match cur_by_name.get(d.name.as_str()) {
            Some(f) => Some(*f),
            None => match &d.renamed_from {
                Some(old) if !des_names.contains(old.as_str()) && !matched.contains(old.as_str()) => {
                    cur_by_name.get(old.as_str()).copied()
                }
                Some(old) => {
                    warnings.push(format!("field {coll}.{}: renamed_from `{old}` ignored (not applicable)", d.name));
                    None
                }
                None => None,
            },
        };
        let d_clean = d.without_hints();
        match existing {
            None => changes.push(Change::AddField { collection: coll.clone(), field: d_clean }),
            Some(c) => {
                matched.insert(c.name.as_str());
                if c.has_column() != d.has_column() {
                    // alias <-> column: cannot be altered in place
                    changes.push(Change::DropField { collection: coll.clone(), field: c.without_hints() });
                    changes.push(Change::AddField { collection: coll.clone(), field: d_clean });
                    continue;
                }
                if c.name != d.name {
                    changes.push(Change::RenameField { collection: coll.clone(), from: c.name.clone(), to: d.name.clone() });
                }
                let mut before = c.without_hints();
                before.name = d.name.clone();
                if before != d_clean {
                    changes.push(Change::AlterField { collection: coll.clone(), before, after: d_clean });
                }
            }
        }
    }
    for c in &cur.fields {
        if !matched.contains(c.name.as_str()) {
            changes.push(Change::DropField { collection: coll.clone(), field: c.without_hints() });
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn snap(yaml: &str) -> Snapshot {
        serde_yaml::from_str(yaml).unwrap()
    }

    #[test]
    fn identical_snapshots_produce_empty_plan() {
        let s = snap(include_str!("../tests/fixtures/pages.yaml"));
        let plan = diff(&s, &s);
        assert!(plan.is_empty(), "{:#?}", plan.changes);
        assert_eq!(plan.from_hash, plan.to_hash);
    }

    #[test]
    fn create_everything_from_empty() {
        let s = snap(include_str!("../tests/fixtures/pages.yaml"));
        let plan = diff(&Snapshot::default(), &s);
        let creates = plan.changes.iter().filter(|c| matches!(c, Change::CreateCollection { .. })).count();
        assert_eq!(creates, 5);
        assert_eq!(plan.max_risk(), Risk::Safe);
    }

    #[test]
    fn rename_add_alter_drop() {
        let current = snap(
            r#"
collections:
  - name: articles
    fields:
      - { name: title, type: string, max_length: 100 }
      - { name: legacy, type: text }
      - { name: views, type: integer }
"#,
        );
        let desired = snap(
            r#"
collections:
  - name: posts
    renamed_from: articles
    fields:
      - { name: headline, type: string, max_length: 200, renamed_from: title }
      - { name: views, type: bigint }
      - { name: body, type: text }
"#,
        );
        let plan = diff(&current, &desired);
        let lines = plan.summary_lines();
        assert!(lines.contains(&"~ collection articles -> posts".to_string()), "{lines:#?}");
        assert!(lines.contains(&"~ field posts.title -> headline".to_string()), "{lines:#?}");
        assert!(lines.iter().any(|l| l.starts_with("~ field posts.headline: type varchar(100) -> varchar(200)")));
        assert!(lines.iter().any(|l| l.starts_with("~ field posts.views: type integer -> bigint")));
        assert!(lines.contains(&"+ field posts.body (text)".to_string()));
        assert!(lines.contains(&"- field posts.legacy (DATA LOSS) [destructive]".to_string()));
        assert!(plan.has_destructive());
    }

    #[test]
    fn policies_matched_by_id() {
        let a = snap(include_str!("../tests/fixtures/pages.yaml"));
        let mut b = a.clone();
        b.policies[0].permissions.push(Permission {
            collection: "categories".into(),
            action: Action::Read,
            fields: vec!["*".into()],
            filter: None,
            validation: None,
            presets: None,
        });
        b.roles[0].name = "Redattore".into();
        let plan = diff(&a, &b);
        assert_eq!(plan.changes.len(), 2);
        assert!(plan.summary_lines().contains(&"~ policy Editor".to_string()));
        assert!(plan.summary_lines().contains(&"~ role Redattore".to_string()));
    }
}
